mapper.select:
SELECT c.id, c.title, c.category, c.type, c.condition_amount, c.discount_amount, c.discount_rate, c.total_count, c.take_count, c.start_time, c.end_time, c.status, c.create_time, IF(cu.id IS NULL, 0, 1) AS is_taken, IF(c.take_count >= c.total_count, 1, 0) AS is_stock_out FROM t_coupon c LEFT JOIN t_coupon_user cu ON c.id = cu.coupon_id AND cu.user_id = #{userId}
c.is_deleted = 0
AND c.category = #{category}
AND c.end_time > NOW()
ORDER BY c.create_time DESC
